// DEBT PAYOFF — which debt to attack first, and what the choice actually costs.
//
// Two orderings are in common use and they optimise different things:
//
//   AVALANCHE  highest interest RATE first. Mathematically optimal: it always pays the least total
//              interest and is never slower.
//   SNOWBALL   smallest BALANCE first. Pays more, sometimes much more — but clears whole accounts
//              sooner, and finishing one is what makes people keep going.
//
// This module does not pick for you. It runs both and reports the difference in money and months, so
// the trade is a number rather than a slogan. That is the honest framing: snowball's cost is real and
// so is its benefit, and only the person paying can weigh them.
//
// EVERYTHING IS INTEGER MINOR UNITS (`money.ts`). A payoff schedule is exactly where float drift shows
// up as a final instalment that is a cent off and a total that will not reconcile.
import { type Money, money, add, subtract, scale, compare, isZero, sum } from "@/features/finance/lib/money";

/** One debt, as the payer knows it. */
export interface Debt {
  /** How the payer refers to it — shown back in the schedule. */
  readonly name: string;
  /** What is owed now. */
  readonly balance: Money;
  /** NOMINAL annual rate as a fraction: 0.2299 for 22.99% APR. */
  readonly apr: number;
  /** The contractual minimum for a period. Paying less is default, so it is never skipped. */
  readonly minimum: Money;
}

export type Strategy = "avalanche" | "snowball";

/** What happened to one debt in one period. */
export interface Payment {
  readonly name: string;
  readonly interest: Money;
  readonly principal: Money;
  readonly balance: Money;
}

export interface Period {
  /** 1-based; period 1 is the first payment made. */
  readonly period: number;
  readonly payments: readonly Payment[];
  /** Debts that reached zero in THIS period — the moment a snowball payer is waiting for. */
  readonly clearedThisPeriod: readonly string[];
}

export interface Plan {
  readonly strategy: Strategy;
  readonly periods: readonly Period[];
  /** How many periods until every balance is zero. */
  readonly months: number;
  readonly totalInterest: Money;
  readonly totalPaid: Money;
  /** Payoff order, in the order each debt actually cleared. */
  readonly order: readonly string[];
}

export class Unpayable extends Error {
  constructor(message: string) {
    super(message);
    this.name = "Unpayable";
  }
}

/** Periodic rate from a nominal annual rate. 12 periods a year unless stated. */
export const periodicRate = (apr: number, periodsPerYear = 12): number => apr / periodsPerYear;

/**
 * The ORDER the strategy attacks in. Ties broken by the other key, then by name, so a run is
 * deterministic — two runs of the same input must produce the same schedule or the comparison below
 * is not reproducible.
 */
export function payoffOrder(debts: readonly Debt[], strategy: Strategy): Debt[] {
  return [...debts].sort((a, b) => {
    if (strategy === "avalanche") {
      if (b.apr !== a.apr) return b.apr - a.apr;
      const byBalance = compare(a.balance, b.balance);
      if (byBalance !== 0) return byBalance;
    } else {
      const byBalance = compare(a.balance, b.balance);
      if (byBalance !== 0) return byBalance;
      if (b.apr !== a.apr) return b.apr - a.apr;
    }
    return a.name.localeCompare(b.name);
  });
}

/**
 * Run one strategy to completion.
 *
 * The mechanics, which are the same either way and are what actually retires debt:
 *  - every debt accrues interest on its balance, then takes at least its minimum;
 *  - whatever is left of `monthlyPayment` goes ENTIRELY to the target — the first unpaid debt in
 *    strategy order;
 *  - when a debt clears, its minimum is not saved. It rolls into the next target. That rolling is
 *    the "snowball", and it is why both strategies accelerate rather than run at a constant rate.
 *
 * REFUSES an unpayable plan rather than looping. If the budget cannot cover the minimums, or a
 * balance grows despite paying them, no schedule exists — and returning a truncated one that stops at
 * some arbitrary horizon would look like a plan while being none.
 */
export function payoff(
  debts: readonly Debt[],
  monthlyPayment: Money,
  strategy: Strategy,
  opts: { periodsPerYear?: number; maxPeriods?: number } = {},
): Plan {
  const { periodsPerYear = 12, maxPeriods = 1200 } = opts;
  if (!debts.length) throw new Unpayable("payoff needs at least one debt");
  const currency = monthlyPayment.currency;

  const minimums = sum(debts.map((d) => d.minimum), currency);
  if (compare(monthlyPayment, minimums) < 0) {
    throw new Unpayable(
      `the budget cannot cover the minimum payments (${minimums.minor} minor units of ${currency}); ` +
        "a plan that ignores that is not a plan — the shortfall has to be closed first",
    );
  }

  const live = payoffOrder(debts, strategy).map((d) => ({ ...d, balance: d.balance }));
  const periods: Period[] = [];
  const order: string[] = [];
  let totalInterest = money(0, currency);
  let totalPaid = money(0, currency);

  for (let p = 1; live.some((d) => !isZero(d.balance)); p++) {
    if (p > maxPeriods) {
      throw new Unpayable(
        `no payoff within ${maxPeriods} periods — at this budget the interest is outrunning the ` +
          "payments, which is a fact worth stating rather than a schedule worth returning",
      );
    }
    let budget = monthlyPayment;
    const payments: Payment[] = [];
    const cleared: string[] = [];

    // 1 — interest, then the contractual minimum on every live debt.
    for (const d of live) {
      if (isZero(d.balance)) continue;
      const interest = scale(d.balance, periodicRate(d.apr, periodsPerYear));
      const owed = add(d.balance, interest);
      // Never pay more than clears it, and never less than the minimum — unless the debt is smaller
      // than its own minimum, in which case the payoff amount IS the payment.
      const wanted = compare(d.minimum, owed) < 0 ? d.minimum : owed;
      const pay = compare(wanted, budget) < 0 ? wanted : budget;
      budget = subtract(budget, pay);
      const principal = subtract(pay, interest);
      d.balance = subtract(owed, pay);
      totalInterest = add(totalInterest, interest);
      totalPaid = add(totalPaid, pay);
      payments.push({ name: d.name, interest, principal, balance: d.balance });
    }

    // 2 — everything left attacks the TARGET, in strategy order.
    for (const d of live) {
      if (isZero(budget)) break;
      if (isZero(d.balance)) continue;
      const extra = compare(d.balance, budget) < 0 ? d.balance : budget;
      budget = subtract(budget, extra);
      d.balance = subtract(d.balance, extra);
      totalPaid = add(totalPaid, extra);
      const row = payments.find((x) => x.name === d.name);
      if (row) {
        payments[payments.indexOf(row)] = {
          ...row,
          principal: add(row.principal, extra),
          balance: d.balance,
        };
      }
    }

    for (const d of live) {
      if (isZero(d.balance) && !order.includes(d.name)) {
        order.push(d.name);
        cleared.push(d.name);
      }
    }
    periods.push({ period: p, payments, clearedThisPeriod: cleared });
  }

  return { strategy, periods, months: periods.length, totalInterest, totalPaid, order };
}

/** What choosing snowball over avalanche costs — the number the decision actually turns on. */
export interface Comparison {
  readonly avalanche: Plan;
  readonly snowball: Plan;
  /** Extra interest snowball pays. Never negative: avalanche is optimal on interest by construction. */
  readonly extraInterest: Money;
  /** Extra periods snowball takes. Never negative. */
  readonly extraMonths: number;
  /** How much sooner snowball clears its FIRST debt — what it buys for that cost. */
  readonly firstClearedSooner: number;
}

export function compareStrategies(
  debts: readonly Debt[],
  monthlyPayment: Money,
  opts: { periodsPerYear?: number; maxPeriods?: number } = {},
): Comparison {
  const avalanche = payoff(debts, monthlyPayment, "avalanche", opts);
  const snowball = payoff(debts, monthlyPayment, "snowball", opts);
  const firstCleared = (p: Plan): number =>
    p.periods.find((x) => x.clearedThisPeriod.length)?.period ?? p.months;
  return {
    avalanche,
    snowball,
    extraInterest: subtract(snowball.totalInterest, avalanche.totalInterest),
    extraMonths: snowball.months - avalanche.months,
    firstClearedSooner: firstCleared(avalanche) - firstCleared(snowball),
  };
}

