import { describe, it, expect } from "vitest";
import { fromMajor, money, toMajor, isZero, type Money } from "@/features/finance/lib/money";
import { payoff, payoffOrder, compareStrategies, periodicRate, Unpayable, type Debt } from "@/features/finance/lib/payoff";

const usd = (major: number): Money => fromMajor(major, "USD");
const debt = (name: string, balance: number, apr: number, minimum: number): Debt => ({
  name, balance: usd(balance), apr, minimum: usd(minimum),
});

// A shape that actually occurs: a small cheap loan, a big expensive card, a middling one.
const DEBTS: Debt[] = [
  debt("card-A", 2500, 0.2299, 50),
  debt("loan-B", 800, 0.0699, 40),
  debt("card-C", 5000, 0.1899, 100),
];

describe("payoffOrder", () => {
  it("avalanche takes the highest RATE first; snowball the smallest BALANCE", () => {
    expect(payoffOrder(DEBTS, "avalanche").map((d) => d.name)).toEqual(["card-A", "card-C", "loan-B"]);
    expect(payoffOrder(DEBTS, "snowball").map((d) => d.name)).toEqual(["loan-B", "card-A", "card-C"]);
  });

  it("breaks ties deterministically, so two runs agree", () => {
    // Without this the comparison below is not reproducible — and a schedule that changes between
    // runs of the same input is not something anyone can act on.
    const tied = [debt("b", 1000, 0.1, 10), debt("a", 1000, 0.1, 10)];
    expect(payoffOrder(tied, "snowball").map((d) => d.name)).toEqual(["a", "b"]);
    expect(payoffOrder(tied, "avalanche").map((d) => d.name)).toEqual(["a", "b"]);
  });
});

describe("payoff — the schedule", () => {
  it("clears every balance and reports the order they cleared in", () => {
    const p = payoff(DEBTS, usd(400), "avalanche");
    const last = p.periods[p.periods.length - 1];
    expect(last.payments.every((x) => isZero(x.balance))).toBe(true);
    expect(p.order).toHaveLength(3);
    expect(p.months).toBe(p.periods.length);
  });

  it("ROLLS a cleared debt's payment into the next target", () => {
    // This is what makes either strategy accelerate. Without the roll, the last debt would take as
    // long as if it were alone, and the whole method would be pointless.
    const p = payoff(DEBTS, usd(400), "snowball");
    const firstCleared = p.periods.find((x) => x.clearedThisPeriod.length)!;
    const after = p.periods[firstCleared.period]; // the period AFTER one cleared
    const target = p.order[1];
    const before = firstCleared.payments.find((x) => x.name === target)!;
    const now = after.payments.find((x) => x.name === target)!;
    expect(now.principal.minor).toBeGreaterThan(before.principal.minor);
  });

  it("never pays more than clears a debt", () => {
    // Overpaying would show as a negative balance, which is not a debt — it is a modelling error that
    // would then be summed into the totals.
    const p = payoff(DEBTS, usd(900), "avalanche");
    for (const period of p.periods) {
      for (const x of period.payments) expect(x.balance.minor).toBeGreaterThanOrEqual(0);
    }
  });

  it("totals reconcile: everything paid is principal plus interest", () => {
    const p = payoff(DEBTS, usd(400), "avalanche");
    const principal = p.periods.flatMap((x) => x.payments).reduce((a, x) => a + x.principal.minor, 0);
    const interest = p.periods.flatMap((x) => x.payments).reduce((a, x) => a + x.interest.minor, 0);
    // Every cent paid went somewhere, and the starting balances were exactly retired.
    expect(principal).toBe(DEBTS.reduce((a, d) => a + d.balance.minor, 0));
    expect(interest).toBe(p.totalInterest.minor);
    expect(p.totalPaid.minor).toBe(principal + interest);
  });
});

describe("payoff — refusals", () => {
  it("REFUSES a budget below the minimums rather than returning a fantasy", () => {
    // The shortfall is the finding. A schedule that quietly ignored it would look like a plan.
    expect(() => payoff(DEBTS, usd(100), "avalanche")).toThrow(Unpayable);
  });

  it("REFUSES when interest outruns the payment, rather than looping to a horizon", () => {
    // Minimums are covered, but they are all interest — the balance never falls. Returning a
    // truncated schedule would show a payoff that does not exist.
    const stuck = [debt("payday", 1000, 3.0, 10)];
    expect(() => payoff(stuck, usd(10), "avalanche", { maxPeriods: 60 })).toThrow(Unpayable);
  });

  it("needs at least one debt", () => {
    expect(() => payoff([], usd(100), "avalanche")).toThrow(Unpayable);
  });
});

describe("compareStrategies — the trade, as a number", () => {
  it("avalanche is NEVER beaten on interest or on months", () => {
    // The mathematical claim the module rests on. If this fails, the advice it supports is wrong.
    const c = compareStrategies(DEBTS, usd(400));
    expect(c.extraInterest.minor).toBeGreaterThanOrEqual(0);
    expect(c.extraMonths).toBeGreaterThanOrEqual(0);
  });

  it("holds across many budgets, not just the one that was convenient", () => {
    for (const budget of [200, 250, 300, 400, 600, 1000]) {
      const c = compareStrategies(DEBTS, usd(budget));
      expect(c.extraInterest.minor, `budget ${budget}`).toBeGreaterThanOrEqual(0);
      expect(c.extraMonths, `budget ${budget}`).toBeGreaterThanOrEqual(0);
    }
  });

  it("names what snowball BUYS — the first debt gone sooner", () => {
    // The cost is real and so is the benefit. Reporting only the cost would be advocacy, not a tool.
    const c = compareStrategies(DEBTS, usd(400));
    expect(c.snowball.order[0]).toBe("loan-B");
    expect(c.avalanche.order[0]).toBe("card-A");
    expect(c.firstClearedSooner).toBeGreaterThan(0);
  });

  it("agrees with itself when there is only one debt — no strategy to choose", () => {
    const one = [debt("only", 1000, 0.1, 50)];
    const c = compareStrategies(one, usd(200));
    expect(c.extraInterest.minor).toBe(0);
    expect(c.extraMonths).toBe(0);
  });
});

describe("periodicRate", () => {
  it("divides the nominal annual rate by the periods in a year", () => {
    expect(periodicRate(0.12)).toBeCloseTo(0.01, 12);
    expect(periodicRate(0.12, 4)).toBeCloseTo(0.03, 12);
  });
});
